-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "026b6539-0a22-5558-95ab-eb5bb3c5a64b", "source": "Arkansas Department of Education, April 2010 released Geometry Q23, physical p13; https://released-math-exams.weebly.com/uploads/2/7/0/8/27087321/arkansas_g_apr_10.pdf", "review_note": "Recovered the original labeled geometry and checked the proof. Removed the incorrect old statement identifying angle 3 as an exterior angle.", "explanation": "Line ZYT is a transversal of the parallel lines XZ and YR. Angles 1 and 5 lie in the same relative position at the two intersections, so they are corresponding angles. Corresponding angles formed by parallel lines are congruent, which justifies Step 2.", "correct": "C", "release": true, "before": {"stem": "Given: △XYZ and XZ ∥ YR. Prove: m∠1 + m∠2 + m∠3 = 180°.\n[Figure: Triangle XYZ with Z at left, Y at right on line ZYT extended to T; R up-right such that YR ∥ XZ; ∠1 at Z, ∠2 at X, ∠3 = ∠XYT interior at Y, ∠4 between XY and YR, ∠5 = ∠RYT.]\nProof: 1. XZ ∥ YR (Given); 2. ∠1 ≅ ∠5 (?); 3. ∠2 ≅ ∠4 (Alternate interior angles of parallel lines are congruent); 4. m∠3 + m∠4 + m∠5 = 180° (∠ZYT is a straight angle); 5. m∠1 + m∠2 + m∠3 = 180° (Substitution)\nWhat is the reason in Step 2?", "choices": [{"key": "A", "text": "Vertical angles are congruent."}, {"key": "B", "text": "Complementary angles are congruent."}, {"key": "C", "text": "Corresponding angles of parallel lines are congruent."}, {"key": "D", "text": "Alternate interior angles of parallel lines are congruent."}], "correct": "C", "explanation": "Source-keyed answer from book_t10.md (T10-44)."}, "fields": {"stem": "Given triangle XYZ with XZ ∥ YR, the labeled angles are used to prove m∠1 + m∠2 + m∠3 = 180°.\nStep 1: XZ ∥ YR (given).\nStep 2: ∠1 ≅ ∠5 (reason missing).\nStep 3: ∠2 ≅ ∠4 (alternate interior angles).\nStep 4: m∠3 + m∠4 + m∠5 = 180° (straight angle ZYT).\nStep 5: m∠1 + m∠2 + m∠3 = 180° (substitution).\nWhat is the reason in Step 2?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "5d2f5f27-f24a-5124-a7e5-edb068bac5e0", "source": "Arkansas Department of Education, April 2010 released Geometry Q23, physical p13; https://released-math-exams.weebly.com/uploads/2/7/0/8/27087321/arkansas_g_apr_10.pdf", "review_note": "Recovered the original labeled geometry and checked the proof. Removed the incorrect old statement identifying angle 3 as an exterior angle.", "explanation": "Line ZYT is a transversal of the parallel lines XZ and YR. Angles 1 and 5 lie in the same relative position at the two intersections, so they are corresponding angles. Corresponding angles formed by parallel lines are congruent, which justifies Step 2.", "correct": "C", "release": true, "before": {"stem": "Given: △XYZ and XZ ∥ YR. Prove: m∠1 + m∠2 + m∠3 = 180°.\n[Figure: Triangle XYZ with Z at left, Y at right on line ZYT extended to T; R up-right such that YR ∥ XZ; ∠1 at Z, ∠2 at X, ∠3 = ∠XYT interior at Y, ∠4 between XY and YR, ∠5 = ∠RYT.]\nProof: 1. XZ ∥ YR (Given); 2. ∠1 ≅ ∠5 (?); 3. ∠2 ≅ ∠4 (Alternate interior angles of parallel lines are congruent); 4. m∠3 + m∠4 + m∠5 = 180° (∠ZYT is a straight angle); 5. m∠1 + m∠2 + m∠3 = 180° (Substitution)\nWhat is the reason in Step 2?", "choices": [{"key": "A", "text": "Vertical angles are congruent."}, {"key": "B", "text": "Complementary angles are congruent."}, {"key": "C", "text": "Corresponding angles of parallel lines are congruent."}, {"key": "D", "text": "Alternate interior angles of parallel lines are congruent."}], "correct": "C", "explanation": "Source-keyed answer from book_t10.md (T10-44)."}, "fields": {"stem": "Given triangle XYZ with XZ ∥ YR, the labeled angles are used to prove m∠1 + m∠2 + m∠3 = 180°.\nStep 1: XZ ∥ YR (given).\nStep 2: ∠1 ≅ ∠5 (reason missing).\nStep 3: ∠2 ≅ ∠4 (alternate interior angles).\nStep 4: m∠3 + m∠4 + m∠5 = 180° (straight angle ZYT).\nStep 5: m∠1 + m∠2 + m∠3 = 180° (substitution).\nWhat is the reason in Step 2?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}, "figure_from_id": "026b6539-0a22-5558-95ab-eb5bb3c5a64b"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260929' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260929','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260929','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-29-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-29-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-29-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260929','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260929'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260929')) AS result;
